onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl11_b1") then dialog.setSkipEnabled(true) end		repeat		    if dialog.show("Level11-1", faceWunai) ==1 then break end			if dialog.show("Level11-2", faceDeyi) ==1 then break end			sound.play("58-1")			if dialog.show("Level11-3", faceZhoumei) ==1 then break end			if dialog.show("Level11-4", faceShijin) ==1 then break end			global.setBool("lvl11_b1")		until true		dialog.setSkipEnabled(false)    game.success()end